// Checks the settings and the request before the workbook is opened.
const item = $input.first();
const { cell_map: map, max_file_mb: maxMb } = item.json;
const own = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);
const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const fail = (status, error, message, problems = []) =>
  [{ json: { ok: false, status, response: { error, message, problems: problems.slice(0, 25) } } }];

function parseAddress(text) {
  if (typeof text !== 'string') return null;
  const cut = text.lastIndexOf('!');
  if (cut < 1) return null;
  let sheet = text.slice(0, cut);
  if (sheet.length > 2 && sheet.startsWith("'") && sheet.endsWith("'")) sheet = sheet.slice(1, -1).replace(/''/g, "'");
  const m = /^\$?([A-Z]{1,3})\$?([1-9][0-9]{0,6})$/.exec(text.slice(cut + 1).toUpperCase());
  if (!m) return null;
  let col = 0;
  for (const ch of m[1]) col = col * 26 + ch.charCodeAt(0) - 64;
  if (col > 16384 || +m[2] > 1048576) return null;
  return { sheet, col, row: +m[2], cell: m[1] + m[2] };
}

// Settings
if (!isObject(map) || !Object.keys(map).length) return fail(500, 'invalid_settings', 'cell_map in Fill Settings must be a JSON object with at least one field.');
if (typeof maxMb !== 'number' || !(maxMb > 0 && maxMb <= 50)) return fail(500, 'invalid_settings', 'max_file_mb in Fill Settings must be a number above 0 and at most 50.');
const targets = new Map();
const usedCells = new Map();
const settingProblems = [];
for (const [field, rule] of Object.entries(map)) {
  const address = typeof rule === 'string' ? rule : rule?.cell;
  const at = parseAddress(address);
  if (!at) { settingProblems.push({ field, cell: String(address ?? ''), reason: 'Bad cell address. Use Sheet!B3.' }); continue; }
  if (isObject(rule) && Object.keys(rule).some((k) => k !== 'cell' && k !== 'values')) { settingProblems.push({ field, cell: address, reason: 'Use only "cell" and "values" in a mapping.' }); continue; }
  if (isObject(rule) && own(rule, 'values') && !isObject(rule.values)) { settingProblems.push({ field, cell: address, reason: '"values" must be a JSON object.' }); continue; }
  const key = JSON.stringify([at.sheet.toLowerCase(), at.cell]);
  if (usedCells.has(key)) { settingProblems.push({ field, cell: address, reason: `Same cell as field "${usedCells.get(key)}".` }); continue; }
  usedCells.set(key, field);
  targets.set(field, { ...at, address, lookup: isObject(rule) && own(rule, 'values') ? rule.values : null });
}
if (settingProblems.length) return fail(500, 'invalid_settings', 'cell_map in Fill Settings is invalid.', settingProblems);

// Uploaded file
const files = Object.keys(item.binary || {});
if (files.length !== 1 || files[0] !== 'template') return fail(400, 'invalid_request', 'Send multipart/form-data with exactly one file, in a field named "template".');
const file = await this.helpers.getBinaryDataBuffer(0, 'template');
if (!file.length) return fail(400, 'empty_file', 'The template file is empty.');
if (file.length > maxMb * 1024 * 1024) return fail(413, 'file_too_large', `The template is larger than ${maxMb} MB.`);
if (file.subarray(0, 8).toString('hex') === 'd0cf11e0a1b11ae1') {
  return file.includes(Buffer.from('EncryptedPackage', 'utf16le'))
    ? fail(415, 'encrypted_workbook', 'Password-encrypted workbooks are not supported. Save a copy without a password.')
    : fail(415, 'old_excel_format', 'Old .xls files are not supported. Save the template as .xlsx or .xlsm.');
}
if (file.subarray(0, 4).toString('hex') !== '504b0304') return fail(415, 'not_a_workbook', 'The file is not an .xlsx or .xlsm workbook.');

// Values
const text = item.json.body?.values;
let values;
try { values = typeof text === 'string' ? JSON.parse(text) : null; } catch (e) { values = null; }
if (!isObject(values) || !Object.keys(values).length) return fail(400, 'invalid_values', 'Send a text field named "values" holding a JSON object with at least one field.');

const problems = [];
const writes = [];
for (const [field, given] of Object.entries(values)) {
  if (!targets.has(field)) { problems.push({ field, reason: 'Unknown field: it is not in cell_map.' }); continue; }
  const { lookup, ...at } = targets.get(field);
  const problem = (reason) => problems.push({ field, cell: at.address, reason });
  if (given !== null && !['string', 'number', 'boolean'].includes(typeof given)) { problem('Use text, a number, true, false or null.'); continue; }
  let value = given === null ? '' : given;
  if (lookup && value !== '') {
    if (!own(lookup, String(value))) { problem('The value is not listed under "values" for this field.'); continue; }
    value = lookup[String(value)];
    if (value === null) value = '';
  }
  let type;
  if (value === '') type = 'clear';
  else if (typeof value === 'boolean') type = 'boolean';
  else if (typeof value === 'number') {
    const size = Math.abs(value);
    if (!Number.isFinite(value) || size > 9.99999999999999e307 || (size && size < 2.2250738585072e-308)) { problem('The number is outside the range Excel supports.'); continue; }
    if (Number.isInteger(value) && size >= 1e15) { problem('Whole numbers over 15 digits lose digits in Excel. Send them as text.'); continue; }
    type = 'number';
  } else if (typeof value === 'string') {
    value = value.replace(/\r\n?/g, '\n');
    if (/[\u0000-\u0008\u000B\u000C\u000E-\u001F￾￿]|\p{Surrogate}/u.test(value)) { problem('The text contains a character that Excel files cannot store.'); continue; }
    if (value.length > 32767) { problem('The text is longer than 32,767 characters.'); continue; }
    if (value.split('\n').length > 254) { problem('The text has more than 253 line breaks.'); continue; }
    type = 'text';
  } else { problem('"values" may only map to text, a number, true, false or null.'); continue; }
  writes.push({ field, ...at, type, value });
}
if (problems.length) return fail(422, 'invalid_values', 'Nothing was filled. Fix every problem and send again.', problems);

const base = String(item.binary.template.fileName || '').split(/[\\/]/).pop()
  .replace(/\.[^.]*$/, '').replace(/[^A-Za-z0-9 _-]/g, '_').trim().slice(0, 80) || 'template';
return [{ json: { ok: true, writes, base }, binary: { archive: { ...item.binary.template, fileExtension: 'zip' } } }];

// Edits only the mapped cells. Returns every archive part with its full path restored for the ZIP node.
const item = $input.first();
const { writes, base } = $('Check Request').first().json;
const fail = (status, error, message, problems = []) =>
  [{ json: { ok: false, status, response: { error, message, problems: problems.slice(0, 25) } } }];
if (item.json.error) return fail(422, 'cannot_unpack', 'The workbook could not be unpacked. It may be damaged.');

const MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const STRICT = 'http://purl.oclc.org/ooxml/spreadsheetml/main';
const REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const CT = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml';
const CT_MACRO = 'application/vnd.ms-excel.sheet.macroEnabled.main+xml';

class Refusal extends Error {}
const refuse = (status, code, message) => { throw Object.assign(new Refusal(message), { status, code }); };
const broken = () => refuse(422, 'invalid_workbook', 'The workbook structure is damaged or not supported.');

// Small XML reader. It records offsets so edits are spliced in and all other text stays as it was.
const ENTITY = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
const decode = (s = '') => s.replace(/&(#x([0-9a-fA-F]+)|#([0-9]+)|amp|lt|gt|quot|apos);/g, (all, e, hex, dec) => {
  if (!hex && !dec) return ENTITY[e];
  const n = hex ? parseInt(hex, 16) : +dec;
  return n <= 0x10ffff ? String.fromCodePoint(n) : all;
});
function parseXml(src, onOpen) {
  const top = { children: [], nsmap: new Map(), ns: '', local: '' };
  const stack = [top];
  let i = 0;
  while ((i = src.indexOf('<', i)) >= 0) {
    const skip = src.startsWith('<!--', i) ? '-->' : src.startsWith('<![CDATA[', i) ? ']]>' : src.startsWith('<?', i) ? '?>' : null;
    if (skip) { const end = src.indexOf(skip, i + 2); if (end < 0) broken(); i = end + skip.length; continue; }
    if (src.startsWith('<!', i)) refuse(422, 'invalid_workbook', 'XML document type declarations are not supported.');
    if (src[i + 1] === '/') {
      const end = src.indexOf('>', i);
      if (end < 0 || stack.length < 2) broken();
      const el = stack.pop();
      if (el.name !== src.slice(i + 2, end).trim()) broken();
      el.closeStart = i; el.end = i = end + 1;
      continue;
    }
    const scan = /[>"']/g;
    scan.lastIndex = i + 1;
    let hit;
    while ((hit = scan.exec(src)) && hit[0] !== '>') {
      const quote = src.indexOf(hit[0], scan.lastIndex);
      if (quote < 0) broken();
      scan.lastIndex = quote + 1;
    }
    if (!hit) broken();
    const openEnd = hit.index + 1;
    const selfClosed = src[hit.index - 1] === '/';
    const body = src.slice(i + 1, selfClosed ? hit.index - 1 : hit.index);
    const name = /^[^\s\/>]+/.exec(body)?.[0];
    if (!name) broken();
    const attrs = new Map();
    const re = /([^\s=\/]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    re.lastIndex = name.length;
    let a;
    while ((a = re.exec(body))) attrs.set(a[1], a[2] ?? a[3]);
    const parent = stack[stack.length - 1];
    let nsmap = parent.nsmap;
    for (const [key, v] of attrs) {
      if (key === 'xmlns' || key.startsWith('xmlns:')) {
        if (nsmap === parent.nsmap) nsmap = new Map(nsmap);
        nsmap.set(key.slice(6), decode(v));
      }
    }
    const colon = name.indexOf(':');
    const prefix = colon < 0 ? '' : name.slice(0, colon);
    const el = { name, prefix: prefix && prefix + ':', local: name.slice(colon + 1), ns: nsmap.get(prefix) || '', nsmap, attrs, parent, children: [], start: i, openEnd, selfClosed };
    if (!onOpen || onOpen(el, parent) !== false) parent.children.push(el);
    if (selfClosed) { el.closeStart = openEnd; el.end = openEnd; } else stack.push(el);
    i = openEnd;
  }
  if (stack.length !== 1 || top.children.length !== 1) broken();
  return top.children[0];
}
const kid = (el, local) => el?.children.find((c) => c.local === local && c.ns === el.ns);
const kids = (el, local) => el?.children.filter((c) => c.local === local && c.ns === el.ns) || [];
const attr = (el, key) => (el?.attrs.has(key) ? decode(el.attrs.get(key)) : undefined);
const isOn = (v) => ['1', 'true', 'on'].includes(v);

const colName = (n) => (n ? colName(Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26)) : '');
function position(ref) {
  const m = /^([A-Z]{1,3})([0-9]+)$/.exec(String(ref).replace(/\$/g, '').toUpperCase());
  if (!m) broken();
  let col = 0;
  for (const ch of m[1]) col = col * 26 + ch.charCodeAt(0) - 64;
  return { col, row: +m[2] };
}
function area(ref) {
  const [a, b = a] = String(ref).split(':');
  return { from: position(a), to: position(b) };
}
const inside = (p, a) => p.row >= a.from.row && p.row <= a.to.row && p.col >= a.from.col && p.col <= a.to.col;

// Archive parts. The unzip node splits each path into directory and fileName.
const parts = new Map();
const binary = {};
for (const [key, meta] of Object.entries(item.binary || {})) {
  const path = meta.directory ? `${meta.directory}/${meta.fileName}` : String(meta.fileName);
  if (path === '__proto__' || path.includes('\\') || path.split('/').some((s) => ['', '.', '..'].includes(s)) || parts.has(path.toLowerCase())) {
    return fail(422, 'invalid_workbook', 'The workbook contains an unsafe or duplicate part name.');
  }
  parts.set(path.toLowerCase(), { key, path });
  binary[key] = { ...meta, fileName: path };
}
const readPart = async (path) => {
  const part = parts.get(path.toLowerCase());
  if (!part) broken();
  const bytes = await this.helpers.getBinaryDataBuffer(0, part.key);
  const text = bytes.toString('utf8');
  if (!Buffer.from(text, 'utf8').equals(bytes)) refuse(422, 'unsupported_encoding', 'Only workbooks with UTF-8 XML are supported.');
  return text;
};
async function readRels(owner) {
  const cut = owner.lastIndexOf('/') + 1;
  const dir = owner.slice(0, cut);
  const path = `${dir}_rels/${owner.slice(cut)}.rels`;
  if (!parts.has(path.toLowerCase())) return [];
  return parseXml(await readPart(path)).children
    .filter((r) => r.local === 'Relationship' && attr(r, 'TargetMode') !== 'External')
    .map((r) => {
      let target = attr(r, 'Target') || '';
      try { target = decodeURIComponent(target); } catch (e) { broken(); }
      const out = [];
      for (const s of (target.startsWith('/') ? target : dir + target).split('/')) {
        if (s === '..') out.pop(); else if (s && s !== '.') out.push(s);
      }
      return { id: attr(r, 'Id'), type: String(attr(r, 'Type')).split('/').pop(), path: out.join('/') };
    });
}

try {
  if (!parts.has('[content_types].xml') || !parts.has('_rels/.rels')) refuse(415, 'not_a_workbook', 'The file is not an .xlsx or .xlsm workbook.');
  const bookPath = (await readRels('')).find((r) => r.type === 'officeDocument')?.path;
  if (!bookPath) refuse(415, 'not_a_workbook', 'The file is not an .xlsx or .xlsm workbook.');
  const bookText = await readPart(bookPath);
  const book = parseXml(bookText);
  if (book.ns === STRICT) refuse(415, 'unsupported_workbook', 'Strict Open XML is not supported. Save as a normal Excel Workbook.');
  const types = parseXml(await readPart('[Content_Types].xml')).children;
  const bookType = attr(types.find((t) => t.local === 'Override' && String(attr(t, 'PartName')).toLowerCase() === `/${bookPath}`.toLowerCase())
    ?? types.find((t) => t.local === 'Default' && String(attr(t, 'Extension')).toLowerCase() === bookPath.split('.').pop().toLowerCase()), 'ContentType');
  if (bookType !== CT && bookType !== CT_MACRO) refuse(415, 'unsupported_workbook', 'Only .xlsx and .xlsm workbooks are supported, not other Office file types.');
  if (book.local !== 'workbook' || book.ns !== MAIN || !kid(book, 'sheets')) broken();

  const bookRels = await readRels(bookPath);
  const sheets = new Map();
  for (const sheet of kids(kid(book, 'sheets'), 'sheet')) {
    const idKey = [...sheet.attrs.keys()].find((k) => k.endsWith(':id') && sheet.nsmap.get(k.slice(0, -3)) === REL);
    sheets.set(String(attr(sheet, 'name')).toLowerCase(), bookRels.find((r) => r.id === attr(sheet, idKey)));
  }

  const problems = [];
  const bySheet = new Map();
  for (const w of writes) {
    const problem = (reason) => problems.push({ field: w.field, cell: w.address, reason });
    const rel = sheets.get(w.sheet.toLowerCase());
    if (!rel) { problem('Sheet not found.'); continue; }
    if (rel.type !== 'worksheet') { problem('This sheet is not a worksheet.'); continue; }
    if (!bySheet.has(rel.path)) bySheet.set(rel.path, []);
    bySheet.get(rel.path).push(w);
  }

  let lockedStyles;
  const changed = new Map();
  for (const [sheetPath, cells] of bySheet) {
    const src = await readPart(sheetPath);
    const wantedRows = new Set(cells.map((c) => c.row));
    const formulaAreas = [];
    let lastRow = 0;
    const root = parseXml(src, (el, parent) => {
      if (el.ns !== MAIN) return;
      if (el.local === 'row' && parent.local === 'sheetData') {
        el.num = lastRow = el.attrs.has('r') ? +el.attrs.get('r') : lastRow + 1;
        el.lastCol = 0;
        el.wanted = wantedRows.has(el.num);
      } else if (el.local === 'c' && parent.local === 'row') {
        if (!parent.wanted) return false;
        el.col = parent.lastCol = el.attrs.has('r') ? position(el.attrs.get('r')).col : parent.lastCol + 1;
      } else if (el.local === 'f' && parent.local === 'c') {
        if (el.attrs.has('ref') && ['array', 'dataTable'].includes(el.attrs.get('t'))) formulaAreas.push(area(el.attrs.get('ref')));
      }
    });
    const data = kid(root, 'sheetData');
    if (root.local !== 'worksheet' || root.ns !== MAIN || !data) broken();

    const merges = kids(kid(root, 'mergeCells'), 'mergeCell').map((m) => area(attr(m, 'ref')));
    const tables = [];
    for (const rel of (await readRels(sheetPath)).filter((r) => r.type === 'table')) {
      const t = parseXml(await readPart(rel.path));
      tables.push({ ...area(attr(t, 'ref')), head: +(attr(t, 'headerRowCount') ?? 1), total: +(attr(t, 'totalsRowCount') ?? 0) });
    }
    const protectedSheet = isOn(attr(kid(root, 'sheetProtection'), 'sheet'));
    if (protectedSheet && !lockedStyles) {
      const path = bookRels.find((r) => r.type === 'styles')?.path;
      lockedStyles = path ? kids(kid(parseXml(await readPart(path)), 'cellXfs'), 'xf')
        .map((xf) => !['0', 'false', 'off'].includes(attr(kid(xf, 'protection'), 'locked'))) : [];
    }
    const rows = kids(data, 'row');
    const columns = kids(kid(root, 'cols'), 'col');

    for (const w of cells) {
      const problem = (reason) => problems.push({ field: w.field, cell: w.address, reason });
      w.rowEl = rows.find((r) => r.num === w.row);
      w.el = kids(w.rowEl, 'c').find((c) => c.col === w.col);
      if (w.el) w.style = attr(w.el, 's');
      else if (w.rowEl && isOn(attr(w.rowEl, 'customFormat'))) w.style = attr(w.rowEl, 's');
      else w.style = attr(columns.find((c) => +attr(c, 'min') <= w.col && w.col <= +attr(c, 'max')), 'style');
      if (kid(w.el, 'f') || formulaAreas.some((a) => inside(w, a))) { problem('The cell holds or belongs to a formula.'); continue; }
      const merge = merges.find((a) => inside(w, a));
      if (merge && (merge.from.row !== w.row || merge.from.col !== w.col)) { problem(`Merged cell: use its top-left cell ${colName(merge.from.col)}${merge.from.row}.`); continue; }
      const table = tables.find((a) => inside(w, a));
      if (table && (w.row < table.from.row + table.head || w.row > table.to.row - table.total)) { problem('Table header and totals cells cannot be filled.'); continue; }
      if (protectedSheet && lockedStyles[+(w.style ?? 0)] !== false) problem('The cell is locked on a protected sheet.');
    }
    if (problems.length) continue;

    const styleAttr = (w) => (/^[0-9]+$/.test(w.style ?? '') && w.style !== '0' ? ` s="${w.style}"` : '');
    const makeCell = (w, p, head, rest = '') => {
      if (w.type === 'clear') return rest ? `<${p}c${head}>${rest}</${p}c>` : `<${p}c${head}/>`;
      if (w.type === 'number') return `<${p}c${head}><${p}v>${w.value}</${p}v>${rest}</${p}c>`;
      if (w.type === 'boolean') return `<${p}c${head} t="b"><${p}v>${w.value ? 1 : 0}</${p}v>${rest}</${p}c>`;
      const safe = w.value.replace(/_(?=x[0-9A-Fa-f]{4}_)/g, '_x005F_').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
      return `<${p}c${head} t="inlineStr"><${p}is><${p}t xml:space="preserve">${safe}</${p}t></${p}is>${rest}</${p}c>`;
    };
    const newCell = (w, p) => makeCell(w, p, ` r="${w.cell}"${styleAttr(w)}`);
    const edits = [];
    const add = (start, end, text) => edits.push({ start, end, text });

    const ordered = [...cells].sort((a, b) => a.row - b.row || a.col - b.col);
    for (const w of ordered.filter((c) => c.el)) {
      let head = '';
      for (const [key, v] of w.el.attrs) if (!['t', 'cm', 'vm'].includes(key)) head += ` ${key}="${v.replace(/"/g, '&quot;')}"`;
      const rest = w.el.children.filter((c) => !(c.ns === MAIN && ['v', 'is'].includes(c.local))).map((c) => src.slice(c.start, c.end)).join('');
      add(w.el.start, w.el.end, makeCell(w, w.el.prefix, head, rest));
    }

    const added = ordered.filter((c) => !c.el && c.type !== 'clear');
    const gaps = new Map();
    const atGap = (pos, text) => gaps.set(pos, (gaps.get(pos) || '') + text);
    for (const row of new Set(added.filter((c) => c.rowEl).map((c) => c.rowEl))) {
      const fresh = added.filter((c) => c.rowEl === row);
      if (row.selfClosed) {
        add(row.start, row.end, `${src.slice(row.start, row.openEnd).replace(/\s*\/>$/, '>')}${fresh.map((w) => newCell(w, row.prefix)).join('')}</${row.name}>`);
      } else {
        for (const w of fresh) atGap(kids(row, 'c').find((c) => c.col > w.col)?.start ?? row.closeStart, newCell(w, row.prefix));
      }
    }
    const p = data.prefix;
    let emptyData = '';
    for (const num of new Set(added.filter((c) => !c.rowEl).map((c) => c.row))) {
      const text = `<${p}row r="${num}">${added.filter((c) => c.row === num).map((w) => newCell(w, p)).join('')}</${p}row>`;
      if (data.selfClosed) emptyData += text;
      else atGap(rows.find((r) => r.num > num)?.start ?? data.closeStart, text);
    }
    if (emptyData) add(data.start, data.end, `${src.slice(data.start, data.openEnd).replace(/\s*\/>$/, '>')}${emptyData}</${data.name}>`);
    for (const [pos, text] of gaps) add(pos, pos, text);

    const dim = kid(root, 'dimension');
    if (dim && added.length) {
      const d = area(attr(dim, 'ref'));
      const r1 = Math.min(d.from.row, ...added.map((c) => c.row)), r2 = Math.max(d.to.row, ...added.map((c) => c.row));
      const c1 = Math.min(d.from.col, ...added.map((c) => c.col)), c2 = Math.max(d.to.col, ...added.map((c) => c.col));
      if (r1 !== d.from.row || r2 !== d.to.row || c1 !== d.from.col || c2 !== d.to.col) {
        add(dim.start, dim.openEnd, src.slice(dim.start, dim.openEnd).replace(/(\sref\s*=\s*)(["'])[^"']*\2/, `$1"${colName(c1)}${r1}:${colName(c2)}${r2}"`));
      }
    }
    changed.set(sheetPath, splice(src, edits));
  }
  if (problems.length) return fail(422, 'cannot_fill', 'Nothing was filled. Fix every problem and send again.', problems);

  // Ask the spreadsheet app to recalculate when it opens the file.
  const calc = kid(book, 'calcPr');
  if (!calc) {
    const after = book.children.filter((c) => c.ns === MAIN && ['sheets', 'functionGroups', 'externalReferences', 'definedNames'].includes(c.local)).pop();
    changed.set(bookPath, splice(bookText, [{ start: after.end, end: after.end, text: `<${book.prefix}calcPr fullCalcOnLoad="1"/>` }]));
  } else if (!isOn(attr(calc, 'fullCalcOnLoad'))) {
    const tag = bookText.slice(calc.start, calc.openEnd).replace(/\sfullCalcOnLoad\s*=\s*(["'])[^"']*\1/, '');
    changed.set(bookPath, splice(bookText, [{ start: calc.start, end: calc.openEnd, text: tag.replace(/\s*(\/?>)$/, ' fullCalcOnLoad="1"$1') }]));
  }

  for (const [path, text] of changed) {
    const part = parts.get(path.toLowerCase());
    const meta = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), part.path, 'application/xml');
    binary[part.key] = { ...meta, fileName: part.path };
  }
  return [{ json: { ok: true, part_fields: Object.keys(binary).join(','), file_name: `${base}-filled.${bookType === CT_MACRO ? 'xlsm' : 'xlsx'}` }, binary }];
} catch (e) {
  if (e instanceof Refusal) return fail(e.status, e.code, e.message);
  throw e;
}

function splice(src, edits) {
  let out = '';
  let at = 0;
  for (const e of [...edits].sort((a, b) => a.start - b.start || a.end - b.end)) {
    out += src.slice(at, e.start) + e.text;
    at = e.end;
  }
  return out + src.slice(at);
}
